#!/usr/bin/env node
/**
 * CleanHostel - VIT-V room cleaning app
 * Single-file Node.js server. No npm install, no build tools, no dependencies.
 * Uses only Node.js built-in modules (http). Requires Node.js to be installed
 * (comes pre-installed on most systems; check with: node -v).
 *
 * HOW TO RUN:
 *   1. Save this file as app.js
 *   2. Open a terminal in the same folder
 *   3. Run:  node app.js
 *   4. Open the printed URL (http://localhost:3000) in your browser
 *
 * The original HTML/CSS/JS app is embedded below (base64-encoded) and is
 * served byte-for-byte identical to the original file, so the output/behaviour
 * is exactly the same as opening the .html file directly.
 */

const http = require("http");

const PORT = process.env.PORT || 3000;

// The full original app (HTML + CSS + JS), base64-encoded so it can be
// embedded safely inside this single .js file with no escaping issues.
const PAGE_B64 = "";

const PAGE_HTML = Buffer.from(PAGE_B64, "base64").toString("utf8");

const server = http.createServer((req, res) => {
  res.writeHead(200, {
    "Content-Type": "text/html; charset=utf-8",
    "Cache-Control": "no-cache"
  });
  res.end(PAGE_HTML);
});

server.listen(PORT, () => {
  console.log("CleanHostel is running!");
  console.log("Open this in your browser: http://localhost:" + PORT);
  console.log("Press Ctrl+C to stop the server.");
});
